import Foundation

// MARK: - SquidPaths

/// Where the generated files live. Config and logs go in `$XDG_CONFIG_HOME/squidmanager`,
/// or `~/.config/squidmanager` when the variable is unset or not absolute. Squid's config
/// parser splits on spaces, so none of these paths may contain one.
public struct SquidPaths: Equatable, Sendable {

  // MARK: Lifecycle

  public init(
    home: URL = FileManager.default.homeDirectoryForCurrentUser,
    environment: [String: String] = ProcessInfo.processInfo.environment
  ) {
    let xdg = environment["XDG_CONFIG_HOME"] ?? ""
    let configHome =
      if xdg.hasPrefix("/") {
        URL(fileURLWithPath: xdg)
      } else {
        home.appendingPathComponent(".config")
      }
    root = configHome.appendingPathComponent("squidmanager")
    logs = root.appendingPathComponent("logs")
    cache = home.appendingPathComponent("Library/Caches/SquidManager")
  }

  // MARK: Public

  /// Written to `root/.gitignore` so a dotfiles repo that tracks `root` skips runtime files.
  public static let gitignoreText = "logs/\nsquid.pid\n"

  public var root: URL
  public var logs: URL
  public var cache: URL

  public var config: URL {
    root.appendingPathComponent("squid.conf")
  }

  public var gitignore: URL {
    root.appendingPathComponent(".gitignore")
  }

  public var passwd: URL {
    root.appendingPathComponent("passwd")
  }

  public var pidFile: URL {
    root.appendingPathComponent("squid.pid")
  }

  public var accessLog: URL {
    logs.appendingPathComponent("access.log")
  }

  public var cacheLog: URL {
    logs.appendingPathComponent("cache.log")
  }

  public var stderrLog: URL {
    logs.appendingPathComponent("stderr.log")
  }
}

// MARK: - SquidConfig

public enum SquidConfig {

  // MARK: Public

  public struct Context: Sendable {
    public init(paths: SquidPaths, hostname: String, authHelper: String?) {
      self.paths = paths
      self.hostname = hostname
      self.authHelper = authHelper
    }

    public var paths: SquidPaths
    public var hostname: String
    /// Path to `basic_ncsa_auth`. Needed only when authentication is on.
    public var authHelper: String?

  }

  public enum BuildError: LocalizedError, Equatable {
    case missingAuthHelper
    case invalidEntry(String)
    case missingParentHost

    public var errorDescription: String? {
      switch self {
      case .missingAuthHelper: "basic_ncsa_auth was not found next to the squid binary."
      case .invalidEntry(let e): "Entry \"\(e)\" contains spaces."
      case .missingParentHost: "Parent proxy is on but has no hostname."
      }
    }
  }

  public static let defaultTemplate = """
    # Generated by SquidManager. Edit the template in Settings, not this file.
    # Placeholders such as %HTTP_PORT% are filled in from the other settings tabs.

    http_port %HTTP_PORT%
    visible_hostname %VISIBLE_HOSTNAME%
    pid_filename %PID_FILE%
    shutdown_lifetime 3 seconds

    # Logs
    %ACCESS_LOG%
    cache_store_log none
    cache_log %CACHE_LOG%
    logfile_rotate 5

    # Cache
    %CACHE_DIR%
    maximum_object_size %MAX_OBJECT_SIZE%
    cache_mem %MEMORY_CACHE_SIZE%
    maximum_object_size_in_memory %MEMORY_MAX_OBJECT_SIZE%
    coredump_dir %CACHE_PATH%

    # DNS
    %DNS%

    # Parent proxy
    %PARENT%

    # Hide the fact that requests pass through a proxy
    %ANONYMIZE%

    # Authentication
    %AUTH%

    # Access control
    acl SSL_ports port 443
    acl Safe_ports port 80          # http
    acl Safe_ports port 21          # ftp
    acl Safe_ports port 443         # https
    acl Safe_ports port 70          # gopher
    acl Safe_ports port 210         # wais
    acl Safe_ports port 1025-65535  # unregistered ports
    acl Safe_ports port 280         # http-mgmt
    acl Safe_ports port 488         # gss-http
    acl Safe_ports port 591         # filemaker
    acl Safe_ports port 777         # multiling http
    acl CONNECT method CONNECT
    %CLIENT_ACLS%

    http_access deny !Safe_ports
    http_access deny CONNECT !SSL_ports
    http_access allow localhost manager
    http_access deny manager
    http_access deny to_localhost
    http_access allow localhost
    %HTTP_ACCESS%
    http_access deny all

    refresh_pattern ^ftp:             1440  20%  10080
    refresh_pattern -i (/cgi-bin/|\\?)  0     0%   0
    refresh_pattern .                 0     20%  4320

    """

  public static func build(_ s: ProxySettings, _ ctx: Context) throws -> String {
    let clients = clean(s.allowedClients)
    for entry in clients + clean(s.directHosts) where entry.contains(where: \.isWhitespace) {
      throw BuildError.invalidEntry(entry)
    }
    let p = ctx.paths

    var access = [String]()
    var clientACLs = [String]()
    if !clients.isEmpty {
      clientACLs = clients.map { "acl allowed_clients src \($0)" }
      access.append("http_access allow allowed_clients")
    }

    var auth = ""
    if s.requireAuth {
      guard let helper = ctx.authHelper else { throw BuildError.missingAuthHelper }
      auth = """
        auth_param basic program \(helper) \(p.passwd.path)
        auth_param basic children 5 startup=1 idle=1
        auth_param basic realm Proxy
        auth_param basic credentialsttl 2 hours
        acl authenticated proxy_auth REQUIRED
        """
      access.append("http_access allow authenticated")
    }

    let listen = s.listenAddress.trimmingCharacters(in: .whitespaces)
    let hostname = s.visibleHostname.trimmingCharacters(in: .whitespaces)
    let dns = s.dnsServers.split(whereSeparator: { $0 == "," || $0.isWhitespace })

    let values: [String: String] = [
      "HTTP_PORT": listen.isEmpty ? "\(s.port)" : "\(listen):\(s.port)",
      "VISIBLE_HOSTNAME": hostname.isEmpty ? ctx.hostname : hostname,
      "PID_FILE": p.pidFile.path,
      "ACCESS_LOG": s.logRequests ? "access_log stdio:\(p.accessLog.path)" : "access_log none",
      "CACHE_LOG": p.cacheLog.path,
      "CACHE_DIR": s.cacheSizeMB > 0
        ? "cache_dir ufs \(p.cache.path) \(s.cacheSizeMB) 16 256"
        : "cache deny all",
      "CACHE_PATH": p.cache.path,
      "MAX_OBJECT_SIZE": s.maxObjectSize,
      "MEMORY_CACHE_SIZE": s.memoryCacheSize,
      "MEMORY_MAX_OBJECT_SIZE": s.memoryMaxObjectSize,
      "DNS": dns.isEmpty ? "" : "dns_nameservers " + dns.joined(separator: " "),
      "PARENT": try parentLines(s),
      "ANONYMIZE": s.anonymize ? anonymizeLines : "",
      "AUTH": auth,
      "CLIENT_ACLS": clientACLs.joined(separator: "\n"),
      "HTTP_ACCESS": access.joined(separator: "\n"),
    ]

    var out = s.template
    for (key, value) in values {
      out = out.replacingOccurrences(of: "%\(key)%", with: value)
    }
    return out
  }

  /// An IPv4/IPv6 address or subnet goes into a `dst` ACL; anything else is treated as a domain.
  public static func isAddress(_ entry: String) -> Bool {
    if entry.contains(":") { return true }
    return entry.range(of: #"^\d{1,3}(\.\d{1,3}){3}(/\d{1,2})?$"#, options: .regularExpression) != nil
  }

  // MARK: Internal

  /// Squid adds "Cache-Control: max-age=<refresh_pattern max>" to every request that lacks one,
  /// which gives the proxy away. Stripping the header also drops the client's own Cache-Control.
  static let anonymizeLines = """
    via off
    forwarded_for delete
    request_header_access Cache-Control deny all
    httpd_suppress_version_string on
    """

  // MARK: Private

  private static func clean(_ list: [String]) -> [String] {
    list.map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
  }

  private static func parentLines(_ s: ProxySettings) throws -> String {
    guard s.useParent else { return "" }
    let host = s.parentHost.trimmingCharacters(in: .whitespaces)
    guard !host.isEmpty else { throw BuildError.missingParentHost }

    var peer = "cache_peer \(host) parent \(s.parentPort) 0 no-query no-digest default"
    if !s.parentUser.isEmpty {
      peer += " login=\(s.parentUser):\(s.parentPassword)"
    }
    var lines = [peer]
    let direct = clean(s.directHosts)
    let ips = direct.filter(isAddress)
    let domains = direct.filter { !isAddress($0) }
    lines += ips.map { "acl direct_ips dst \($0)" }
    lines += domains.map { "acl direct_domains dstdomain \($0)" }
    if !ips.isEmpty { lines.append("always_direct allow direct_ips") }
    if !domains.isEmpty { lines.append("always_direct allow direct_domains") }
    lines.append("never_direct allow all")
    return lines.joined(separator: "\n")
  }

}
